    pub fn txtime(&mut self) -> io::Result<()> {
        let cfg = sock_txtime {
            clockid: libc::CLOCK_MONOTONIC,
            flags: 0,
        };
        setsockopt(&self.socket.as_fd(), TxTime, &cfg)?;

        self.cap.has_txtime = true;
        Ok(())
    }
